return {
[76247] = {id=76247,name="Keep the Home Fires Burning",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The keyflame braziers, located across the countryside keep the darkness at bay and our people safe. Many have gone dark as the Radiant Remnants needed to maintain them have become harder to find. We've worked hard to ensure our brazier is always lit, but we could always use your help. Please gather remnants from our supplies and use them to help empower our family keyflame.",objectivesText="5 Hillhelm Remnant Supplies gathered and used to empower the Hillhelm Keyflame. Progress: Have you empowered our keyflame?",starts={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},coords={x=0.612,y=0.304,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Keep the Home Fires Burning"},
[76338] = {id=76338,name="A Better Cabbage Smacker",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,objectivesText="Gyro-Optic Springs collected Cleanbrass Bolts collected Find and return Control-Gear to Ezgi",starts={{x=0.65,y=0.293,mapID=2215}},ends={{x=0.65,y=0.293,mapID=2215}},coords={mapID=2215,x=0.65,y=0.293},questType="world",db2Objectives={{orderIndex=0,type=1,amount=8,objectID=206518,text="Gyro-Optic Springs collected"},{orderIndex=1,type=1,amount=5,objectID=206519,text="Cleanbrass Bolts collected"},{orderIndex=2,type=0,amount=1,objectID=215780,text="Find and return Control-Gear to Ezgi"}},worldTaskTitle="A Better Cabbage Smacker"},
[76586] = {id=76586,name="Spreading the Light",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,objectivesText="Lesser Keyflames Activated Radiant Remnant collected from creatures",starts={{x=0.553,y=0.145,mapID=2215}},ends={{x=0.553,y=0.145,mapID=2215}},coords={mapID=2215,x=0.553,y=0.145},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=215815,text="Lesser Keyflames Activated"},{orderIndex=1,type=14,amount=1,objectID=168794,text="Radiant Remnant collected from creatures"}},worldTaskTitle="Spreading the Light",db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[76588] = {id=76588,name="Defender of the Flame",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The Expedition forces face formidable adversaries. Drawn like moths to our keyflames, creatures of all types are intent on snuffing out the light and thwarting our rebuilding efforts. Please help us defeat two of the most menacing denizens that threaten our keyflames. Together, we can drive back this darkness.",objectivesText="Eliminate two rare creatures within the areas controlled by the keyflames. Progress: Have you eliminated the threats?",starts={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},ends={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},coords={x=0.654,y=0.322,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Defender of the Flame"},
[78457] = {id=78457,name="Stones of Dornogal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2248,description="I am Merrix , Councilward of Dornogal. I appreciate your aid--especially in light of the fraught nature of your arrival. You must forgive Stormward Baelgrim. Being suspicious is part of his directive. A formal discussion of our situation is warranted. If you wish to strike back at the nerubians, as we do, meet us at the Foundation Hall. Baelgrim and I need to review the data so far. In the meantime, you are my guest. Take my ring. It will allow you to access Dornogal's amenities.",objectivesText="Meet with various earthen citizens in Dornogal. Progress: The attack seems concentrated on the Coreway. The rest of the city is secure, but we should ready ourselves for anything.",starts={{npcID=217854,x=0.294,y=0.596,zoneID=14771}},ends={{npcID=217861,x=0.4,y=0.258,zoneID=14771}},coords={x=0.294,y=0.596,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Stones of Dornogal"},
[78590] = {id=78590,name="Cutting Edge",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,objectivesText="Fungal Enemies slain Hallowfall Scythe collected",starts={{x=0.638,y=0.319,mapID=2215}},ends={{x=0.638,y=0.319,mapID=2215}},coords={mapID=2215,x=0.638,y=0.319},questType="world",db2Objectives={{orderIndex=0,type=0,amount=60,objectID=214001,text="Fungal Enemies slain"},{orderIndex=1,type=0,amount=1,objectID=212806,text="Hallowfall Scythe collected"}},worldTaskTitle="Cutting Edge"},
[78607] = {id=78607,name="To Mereldar",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We must get to Mereldar and let General Steelstrike know what the Order of Night tried here. Thank the Sacred Flame we stopped them before they could do any worse.",objectivesText="Travel to Mereldar and meet with General Steelstrike.",starts={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},ends={{npcID=214364,x=0.434,y=0.486,zoneID=14838}},coords={x=0.562,y=0.42,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="To Mereldar"},
[78613] = {id=78613,name="The Bastion of Hallowfall",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I have to admit, I did not think that the first visitors we'd have in Mereldar would have been outsiders. I thought the Empire... Well, nevermind. You have been more than helpful to my people, and that deserves recognition. Mereldar is the bastion of the Arathi in Hallowfall . Take some time, rest.",objectivesText="Explore Mereldar. Progress: This city has much to see.",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=220124,x=0.426,y=0.556,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="The Bastion of Hallowfall"},
[78618] = {id=78618,name="Fungal Frenzy",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,objectivesText="Defeat the Fungarians Fungarian Fungarian 2 Wildlife",starts={{x=0.535,y=0.664,mapID=2248}},ends={{x=0.535,y=0.664,mapID=2248}},coords={mapID=2248,x=0.535,y=0.664},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Defeat the Fungarians"},{orderIndex=1,type=0,amount=17,objectID=213109,text="Fungarian"},{orderIndex=3,type=0,amount=20,objectID=213103,text="Wildlife"},{orderIndex=2,type=0,amount=13,objectID=213110,text="Fungarian 2"}},worldTaskTitle="Fungal Frenzy"},
[78620] = {id=78620,name="Crossroads of Twilight",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We need to take the Veneration Grounds back from the kobyss. Push them back and pave a bloody path through them. We need to stop whatever is happening at the Eternal Flame! If they manage to corrupt it like they did at the tower... I don't even want to imagine what will happen.",objectivesText="Kill 15 kobyss attackers in the Veneration Grounds in Hallowfall . Progress: Flames, they just keep coming.",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Crossroads of Twilight"},
[78624] = {id=78624,name="A Candle in the Dark",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Beledar has turned to Shadow, we must retreat back to Mereldar! Aelric Leid .> I-- No. We need to destroy Aelric first. Take him down, then we retreat.",objectivesText="Kill Aelric Leid in the Veneration Grounds in Hallowfall .",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=225188,x=0.336,y=0.546,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="A Candle in the Dark"},
[78627] = {id=78627,name="The Final Front",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Just before the kobyss attacked, we received word of a disturbance near Livia's Patience. Now we know the cause. We... Light... We can't survive fighting on two fronts, . We have to stop this, now.",objectivesText="Travel to Light's Redoubt in Hallowfall .",starts={{npcID=225188,x=0.336,y=0.546,zoneID=14838}},ends={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},coords={x=0.336,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="The Final Front"},
[78628] = {id=78628,name="Trapdoor Sprung",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We need time to get the Reckoning ready. Take your friends and hold back the nerubians for as long as you can. They deserve nothing but death for what they have done to our people.",objectivesText="Kill 15 nerubians in Livia's Patience in Hallowfall . Progress: How goes the hunt?",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Trapdoor Sprung"},
[78629] = {id=78629,name="Running on Reserves",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We have to try to save any of our people left alive in Livia's Patience. Every Arathi is or was a member of the military. If you can help them, they'll be able to help themselves.",objectivesText="Assist 5 Arathi Reserves in Livia's Patience in Hallowfall . Progress: I managed to rescue a few, did you find people to rescue?",starts={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},ends={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},coords={x=0.41,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Running on Reserves"},
[78630] = {id=78630,name="The Rise of the Reckoning",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The Reckoning is ready! Let's make these spiders pay. Blood for blood.",objectivesText="Board The Reckoning and slay 150 nerubian forces. Progress: We will make the nerubians regret ever thinking they could push into our home!",starts={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},ends={{npcID=211699,x=0.294,y=0.422,zoneID=14752}},coords={x=0.41,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="The Rise of the Reckoning"},
[78657] = {id=78657,name="The Midnight Sentry",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,objectivesText="Enemy revealed using Sentry Flare",starts={{x=0.639,y=0.196,mapID=2215}},ends={{x=0.639,y=0.196,mapID=2215}},coords={mapID=2215,x=0.639,y=0.196},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=217065,text="Enemy revealed using Sentry Flare"}},worldTaskTitle="The Midnight Sentry"},
[78685] = {id=78685,name="The Tunnel's End",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="So we're hearing more rumors about Taelloch. The town and its mine are responsible for ore production. Apparently, we haven't received shipments in weeks, and the town's foreman has disappeared. Now the High Speaker is discouraging anyone from traveling there. That tells me we should investigate. And of course, if people are hurting, then we should help them.",objectivesText="Investigate the rumors about Taelloch. Progress: We have to find out what happened here.",starts={{npcID=218715,x=0.47,y=0.332,zoneID=14795}},ends={{npcID=213612,x=0.604,y=0.598,zoneID=14795}},coords={x=0.47,y=0.332,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="The Tunnel's End"},
[78696] = {id=78696,name="We Don't Go to Taelloch",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="This troubled Machine Speaker was here to do something. But what? It looks like something really did some damage to him. We shouldn't dally. We need to head into Taelloch and look for the foreman. Can you clear the entryway into the town? Someone could get hurt!",objectivesText="Clear the entrance to Taelloch of encroaching beasts.",starts={{npcID=213612,x=0.604,y=0.598,zoneID=14795}},ends={{npcID=213634,x=0.622,y=0.582,zoneID=14795}},coords={x=0.604,y=0.598,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="We Don't Go to Taelloch"},
[78697] = {id=78697,name="Ghost of a Company Town",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="The foreman isn't here. Obviously. But the evidence points to her being here recently. So perhaps she's still nearby! We should go further into town and see if anyone has any idea where she might be. Or maybe someone else can give us the answers we need. Maybe we'll find out on our own! Maybe it was some sort of attack or some kind of... sorry. I'm getting ahead of myself. Let's go investigate!",objectivesText="Use the Investigate ability to find clues about what happened in Taelloch.",starts={{npcID=213634,x=0.622,y=0.582,zoneID=14795}},ends={{npcID=216479,x=0.66,y=0.584,zoneID=14795}},coords={x=0.622,y=0.582,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="Ghost of a Company Town"},
[78700] = {id=78700,name="Controlled Demolition",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I know we've fought skardyn before, champion, but this... this is worse. I knew that skardyn were turning earthen into more skardyn, but I didn't expect... the crystals... the spikes... the roiling blue energy... that smell! Anyway, not what I expected at all. If we must venture out there, I'm taking down some of those abominations along the way.",objectivesText="Kill 18 skardyn in Taelloch Progress: There's more to be done. We can't let this corruption spread.",starts={{npcID=216479,x=0.66,y=0.584,zoneID=14795}},ends={{mapID=2214,npcID=216479,x=0.64,y=0.584}},coords={x=0.66,y=0.584,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="Controlled Demolition"},
[78701] = {id=78701,name="The Truth in Chalk",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean.... I'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines. And I know the foreman is the key. She has to be.",objectivesText="Search for messages in Taelloch Mine. Progress: There's more to learn here. I'm sure of it.",starts={{x=0.619,y=0.583,mapID=2214,npcID=214892}},ends={{x=0.619,y=0.583,mapID=2214,npcID=214892}},coords={mapID=2214,x=0.619,y=0.583},questType="world",worldTaskTitle="The Truth in Chalk"},
[78703] = {id=78703,name="Buried in Stone",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.",objectivesText="Investigate the cave at the back of the Taelloch Mine Progress: We're missing something... There must be something in that cave!",starts={{npcID=214892}},questType="world",worldTaskTitle="Buried in Stone"},
[78704] = {id=78704,name="Find the Foreman",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Dagran was right. I suppose I shouldn't be surprised by that any longer. All the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers. We've come this far. Let's see what's inside.",objectivesText="Find the foreman. Progress: There must be answers deeper within the cave.",starts={{npcID=214890}},questType="world",worldTaskTitle="Find the Foreman"},
[78705] = {id=78705,name="What She Saw",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="What is that? That thing the skardyn dropped before we... before it died. I think I've seen something like that before.",objectivesText="Investigate the gem left by the skardyn. Progress: I think I know what that gem is...",starts={{npcID=214892}},ends={{npcID=219453,x=0.684,y=0.642,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.671333,y=0.643333},questType="world",worldTaskTitle="What She Saw"},
[78706] = {id=78706,name="The High Speaker's Secret",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We got what we came for. We need to return to Gundargaz. Brinthe has to know what happened here. We'll go on ahead, $p. Meet us in Gundargaz.",objectivesText="Return to Brinthe in Gundargaz.",starts={{npcID=219452,x=0.684,y=0.642,zoneID=14795}},ends={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},coords={x=0.684,y=0.642,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="The High Speaker's Secret"},
[78941] = {id=78941,name="A Tide Needing Turned",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Xal'atath's army has been capable of striking at us for a while now. So what caused her to choose this moment? Something is wrong here. She waited for us to build an army in response, and then attacks openly. We're playing into her hands. Report to the Arathi general. I'll head to the battlefield directly.",objectivesText="Meet with General Steelstrike in Hallowfall .",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=214271,x=0.716,y=0.592,zoneID=14838}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="A Tide Needing Turned"},
[78974] = {id=78974,name="Beetle-Minded",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,objectivesText="Water Trough filled Food Trough filled",starts={{x=0.719,y=0.798,mapID=2255}},ends={{x=0.719,y=0.798,mapID=2255}},coords={mapID=2255,x=0.719,y=0.798},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=214452,text="Water Trough filled"},{orderIndex=1,type=0,amount=4,objectID=214455,text="Food Trough filled"}},worldTaskTitle="Beetle-Minded",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[78995] = {id=78995,name="Truffle Shuffle",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,objectivesText="Kaheti Truffles",starts={{x=0.731,y=0.714,mapID=2255}},ends={{x=0.731,y=0.714,mapID=2255}},coords={mapID=2255,x=0.731,y=0.714},questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=219220,text="Kaheti Truffles"}},worldTaskTitle="Truffle Shuffle",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[79089] = {id=79089,name="Consecrated Cleanup",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Our Veneration Grounds have been desecrated. Its beauty marred. It's going to take a bigger effort, but I would appreciate anything you can do to cleanup our grounds.",objectivesText="Restore the Veneration Grounds in Hallowfall . Progress: I wish you could have seen this place before the Kobyss arrived.",starts={{npcID=225188,x=0.336,y=0.546,zoneID=14838}},ends={{npcID=225188,x=0.336,y=0.546,zoneID=14838}},coords={x=0.336,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Consecrated Cleanup"},
[79116] = {id=79116,name="Spider Optics",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,objectivesText="Rescue Spiderlings Protect Egg Sacs",starts={{x=0.694,y=0.766,mapID=2255}},ends={{x=0.694,y=0.766,mapID=2255}},coords={mapID=2255,x=0.694,y=0.766},questType="world",db2Objectives={{orderIndex=1,type=0,amount=6,objectID=223682,text="Rescue Spiderlings"},{orderIndex=2,type=0,amount=5,objectID=223683,text="Protect Egg Sacs"}},worldTaskTitle="Spider Optics",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[79151] = {id=79151,name="An Orphan's Request",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Wow, you look really strong! Would you be able to help me? My parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. Could you go get it for me?",objectivesText="Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall . Progress: I will make the kobyss regret ever setting foot in these lands.",starts={{npcID=215237,x=0.416,y=0.556,zoneID=14838}},ends={{npcID=218062,x=0.524,y=0.502,zoneID=14838}},coords={x=0.416,y=0.556,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="An Orphan's Request"},
[79152] = {id=79152,name="Gutting the Pool",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The kobyss are... a bit larger than I expected, and I might--might, you understand?--have more trouble with them than I originally anticipated. Kill any stupid fish-faces you see.",objectivesText="Kill 10 kobyss in The Hungering Pool in Hallowfall . Progress: Yes, make them bleed. Make them pay!",starts={{npcID=218062,x=0.524,y=0.502,zoneID=14838}},ends={{npcID=215254,x=0.496,y=0.506,zoneID=14838}},coords={x=0.524,y=0.502,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Gutting the Pool"},
[79153] = {id=79153,name="Vae Victis",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Ah it's time. Kill their leader. Salt his bones, take his head, and laugh as his tribe crumbles! Sharpscale's last moments are upon him, and he doesn't even realize it yet. Stupid fish-face.",objectivesText="Kill Sharpscale the Devourer and retrieve its head in the Hungering Pool in Hallowfall . Progress: His skull would make a good cup I think? Perhaps a mantle ornament?",starts={{npcID=215254,x=0.496,y=0.506,zoneID=14838}},ends={{npcID=215254,x=0.496,y=0.506,zoneID=14838}},coords={x=0.496,y=0.506,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Vae Victis"},
[79154] = {id=79154,name="A Final Goodbye",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Well, parents avenged, fish killed, more fish killed, biggest fish killed. Pretty good day. I guess I should go burn stuff.",objectivesText="Help Alyza say goodbye in the Hungering Pool in Hallowfall .",starts={{npcID=215254,x=0.496,y=0.506,zoneID=14838}},ends={{npcID=219368,x=0.418,y=0.554,zoneID=14838}},coords={x=0.496,y=0.506,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="A Final Goodbye"},
[79165] = {id=79165,name="A Moment to Rest",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Good, you're both here. I have a favor to ask. Faerin's wandered off. I think it might help if you and your... disheveled friend here find her. She'll be in Light's Redoubt.",objectivesText="Find Faerin near Light's Redoubt.",starts={{npcID=215341,x=0.43,y=0.524,zoneID=14838}},ends={{npcID=218541,x=0.406,y=0.708,zoneID=14838}},coords={x=0.43,y=0.524,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="A Moment to Rest"},
[79166] = {id=79166,name="Lost Pieces",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="There was a time when I would have known what words to say to help her. But now... they are as lost to me as everything else. There must be something we can do. Her old Lamplighter companion, this Andari... would have had one of those tinderboxes, right? They seem important for funeral rites. I'll accompany Faerin back to Mereldar and meet you there. If you think there's hope of finding Andari's lost belongings ... could you try to look?",objectivesText="Collect 8 Lost Personal Effects from enemies in the Harrowing Depths. Progress: There's no time to mourn. Not when there's fighting to be done. If you have time to mourn, you have time to train. To make sure we don't lose anyone else.",starts={{npcID=218541,x=0.406,y=0.708,zoneID=14838}},ends={{npcID=215331,x=0.406,y=0.708,zoneID=14838}},coords={x=0.406,y=0.708,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Lost Pieces"},
[79167] = {id=79167,name="Crowdsourcing",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Light's Gambit is an old and honored game. There's a reason so many Arathi play it! It can teach you a lot about strategy. And it can tell you a lot about your opponents. But we're still missing a few pieces that we need in order to play. Sometimes, folks around Mereldar lend us pieces for a game. Could you ask around?",starts={{npcID=215331,x=0.406,y=0.708,mapID=2215}},ends={{npcID=218267,x=0.432,y=0.524,mapID=2215}},coords={x=0.406,y=0.708,source="quest_giver",mapID=2215},questType="world",worldTaskTitle="Crowdsourcing"},
[79168] = {id=79168,name="Light's Gambit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="It's fine! We can catch you up on the rest of the rules later! Resolving combat is the most fun, anyway! You and Anduin can team up against me. Perhaps with the both of you together, you'll stand a chance!",objectivesText="Grab the castle piece to start a game of Light's Gambit with Faerin and Anduin.",starts={{npcID=218267,x=0.432,y=0.524,zoneID=14838}},ends={{npcID=217909,x=0.432,y=0.524,zoneID=14838}},coords={x=0.432,y=0.524,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Light's Gambit"},
[79200] = {id=79200,name="Who am I?",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn , and this is Foreman Uzjax. Many things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it. Like many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. Embrace it.",objectivesText="Complete the first stage in the Awakening Protocol.",starts={{x=0.894,y=0.48,mapID=2322,npcID=221839}},ends={{x=0.894,y=0.48,mapID=2322,npcID=221839}},coords={mapID=2322,x=0.894,y=0.48},questType="world",worldTaskTitle="Who am I?"},
[79201] = {id=79201,name="The Analysis Interface",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.",objectivesText="Complete the Analyzing Sequence in the Analysis Interface.",starts={{x=0.626,y=0.492,mapID=2322,npcID=221891}},ends={{x=0.626,y=0.492,mapID=2322,npcID=221891}},coords={mapID=2322,x=0.626,y=0.492},questType="world",worldTaskTitle="The Analysis Interface"},
[79202] = {id=79202,name="Rock Beats Rock",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="Welcome to the Procedural Forum. Foreman Uzjax informs me that this chamber once served as our assignment testing facility. With his guidance, we've repurposed this chamber. Earthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.",objectivesText="Spar with 6 newly Awakened Earthen. Progress: Whether they were once Storm Riders or Peacekeepers or craftsman and laborers, martial prowess takes time to hone and refine.",starts={{x=0.477,y=0.547,mapID=2322,npcID=221888}},ends={{x=0.477,y=0.547,mapID=2322,npcID=221888}},coords={mapID=2322,x=0.477,y=0.547},questType="world",worldTaskTitle="Rock Beats Rock"},
[79203] = {id=79203,name="Authorization: Negated",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="The Bulwark of Authorization! That's what this chamber was once called. I had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. A golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers. Dawn seems to think you've got what it takes to deal with it. Up to the challenge?",objectivesText="Defeat the Phalanx of Authorization within the Bulwark of Authorization.",starts={{x=0.309,y=0.485,mapID=2322,npcID=221898}},ends={{x=0.309,y=0.485,mapID=2322,npcID=221898}},coords={mapID=2322,x=0.309,y=0.485},questType="world",worldTaskTitle="Authorization: Negated"},
[79204] = {id=79204,name="Whoever You Want to Be",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="After an awakening protocol like that, I can see why Dawn says you're special. The world is not prepared for an earthen like you. Dawn and the Foreman are waiting for you in the Awakening Vestibule. Go on, then! Complete your Awakening Protocol and get out of here!",objectivesText="Speak with Dawn to complete your Awakening Protocol.",starts={{x=0.163,y=0.481,mapID=2322,npcID=221900}},ends={{x=0.163,y=0.481,mapID=2322,npcID=221900}},coords={mapID=2322,x=0.163,y=0.481},questType="world",worldTaskTitle="Whoever You Want to Be"},
[79232] = {id=79232,name="Those Who Fell",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Since the Day of Shadows these lands have been a dangerous place. The kobyss are emboldened, the nerubians probe our lands, creatures of pure shadow have begun to manifest themselves. The memory of those who have fallen is etched in our everyday lives. We must locate their remains to bring closure. Search for the Tinderboxes of these missing expedition members and return them to me.",objectivesText="Locate the remains of Oskaer Daleclash, Dalian Ironlink, and Idona Seerstone, and recover their tinderboxes. Progress: Have you located the tinderboxes?",starts={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},ends={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},coords={x=0.654,y=0.322,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Those Who Fell"},
[79257] = {id=79257,name="Grotto Grievances",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14795,mapID=2214,objectivesText="Living Grotto contained",starts={{x=0.504,y=0.712,mapID=2214}},ends={{x=0.504,y=0.712,mapID=2214}},coords={mapID=2214,x=0.504,y=0.712},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Living Grotto contained"}},worldTaskTitle="Grotto Grievances"},
[79328] = {id=79328,name="Embassies and Envoys",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=14771,mapID=2248,description="I feared what we would find when we returned here, but I am proud to see that though we were forced to leave, you were able to forge a friendship with the earthen and stand against the nerubians. With your strength, we will win this. But first we need a plan, and for that we need space here in Dornogal for discussion.",objectivesText="Set up your faction's embassy in Dornogal.",starts={{npcID=216167,x=0.36,y=0.812,zoneID=14771}},ends={{npcID=214917,x=0.316,y=0.594,zoneID=14771}},coords={x=0.36,y=0.812,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Embassies and Envoys"},
[79329] = {id=79329,name="Glowing Harvest",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,objectivesText="Remnants Satchels collected",starts={{x=0.634,y=0.285,mapID=2215}},ends={{x=0.634,y=0.285,mapID=2215}},coords={mapID=2215,x=0.634,y=0.285},questType="world",db2Objectives={{orderIndex=0,type=1,amount=12,objectID=212755,text="Remnants Satchels collected"}},worldTaskTitle="Glowing Harvest"},
[79333] = {id=79333,name="The Fleet Arrives",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="From the moment we crashed on this isle, it were clear as crystal we'd be needin' allies if we hoped to face Xal'atath. Jaina and Thrall took off tae muster reinforcements, an' you and I set tae work seein' what could be done here with the earthen. An' I have to say we've done well on our own, haven't we? But it looks like our reinforcements may have finally arrived. Peacekeepers spied ships comin' this way. Go take a look an' confirm the good news!",objectivesText="Scout the harbor for ships arriving from the Horde and Alliance fleet.",starts={{npcID=216149,x=0.36,y=0.802,zoneID=14771}},ends={{npcID=216167,x=0.36,y=0.812,zoneID=14771},{npcID=216168,x=0.358,y=0.812,zoneID=14771}},coords={x=0.36,y=0.802,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="The Fleet Arrives"},
[79343] = {id=79343,name="Everyday I'm Snufflin'",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Perhaps the kobolds of Gundargaz would be interested in this Odd Glob of Wax.",objectivesText="Bring the Odd Glob of Wax to Gnawbles in Gundargaz. Progress: You snuffle something good?",starts={{x=0.435,y=0.353,mapID=2214}},ends={{npcID=216164,x=0.476,y=0.352,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.448667,y=0.352},questType="world",worldTaskTitle="Everyday I'm Snufflin'"},
[79344] = {id=79344,name="Urban Odyssey",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Did ye hear, ? A lot of folks from the city are eager to lend a hand an' support our attack on the nerubians and Xal'atath. I think it's worth reachin' out tae them tae see how they could pitch in. The more support we gather, the better.",objectivesText="Ask around Dornogal for pledges of support in the coming conflict. Progress: I am glad to see you return, <name>.",starts={{npcID=214917,x=0.316,y=0.594,zoneID=14771}},ends={{npcID=214917,x=0.316,y=0.594,zoneID=14771}},coords={x=0.316,y=0.594,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Urban Odyssey"},
