[80049] = {id=80049,name="The Flame Still Burns",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="That was too close. This attack took a toll on all of us. We have many injured, and many shaken. Can you check in with people? See how they are doing?",objectivesText="Check in with Arathi Survivors in the Veneration Grounds in Hallowfall . Progress: How's it looking out there?",starts={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},ends={{npcID=225188,x=0.336,y=0.546,zoneID=14838}},coords={x=0.41,y=0.546,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="The Flame Still Burns"},
[80079] = {id=80079,name="A Wrench in the Works",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Looks like the High Speaker is addressing his workers. It seems something has finally shaken them from their complacency, and their time away from the Awakening Machine is affecting them. Perhaps this would be a good opportunity for everyone to hear what they have to say? We should convince a few of these Machine Speakers to speak up.",objectivesText="Encourage members of the crowd to air their grievances. Progress: Recalcitrant lot, aren't they?",starts={{npcID=218714,x=0.47,y=0.332,zoneID=14795}},ends={{npcID=218714,x=0.47,y=0.332,zoneID=14795}},coords={x=0.47,y=0.332,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="A Wrench in the Works"},
