[80592] = {id=80592,name="Forge a Pact",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Let us renew your Pact. Remember, you may only enter a Pact with one of the Severed Threads at a time. These contracts are temporary, though, so you will have many opportunities to prove yourself to all three.",objectivesText="Choose a Severed Threads Pact.",starts={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},ends={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},coords={x=0.552,y=0.412,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Forge a Pact",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[80670] = {id=80670,name="Eyes of the Weaver",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The Weaver's many eyes lurk throughout the city, learning as much as they can about Ansurek's machinations. Still, intelligence enough will not be sufficient to turn the tide against the Sureki forces. The Weaver requires someone willing to get their hands dirty. Lucky you, I suppose.",objectivesText="Continue your efforts in aiding the Weaver in Azj-Kahet. Progress: Chk-chaah! You return at least. What news of the city do you bring me, hrm?",starts={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},ends={{npcID=224734,x=0.564,y=0.432,zoneID=14752}},coords={x=0.552,y=0.412,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Eyes of the Weaver",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[80671] = {id=80671,name="Blade of the General",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Even now, General Anub'azal's forces work tirelessly to ensure the security of Azj-Kahet. Ansurek's reach extends to every corner of her domain. The General seeks to undermine her military authority. If we stretch her resources thin, then we may find new opportunities to strike.",objectivesText="Continue your efforts in aiding the General in Azj-Kahet. Progress: Hrmph. It is about time that you've returned. What news?",starts={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},ends={{npcID=224729,x=0.558,y=0.422,zoneID=14752},{npcID=229184,x=0.558,y=0.422,zoneID=14752}},coords={x=0.552,y=0.412,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Blade of the General",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[80672] = {id=80672,name="Hand of the Vizier",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The Vizier works even now to spread our conspiracy's influence amongst the well-to-do of Azj-Kahet's elite. Given his position, though, he can offer little in the way of direct support. That is where you come in. Your growing reputation precedes you; you can move in ways that the Vizier cannot. Just take care not to get eaten, hrm?",objectivesText="Continue your efforts in aiding the Vizier in Azj-Kahet. Progress: I fear that our task grows more arduous with each passing day. I hope you are not wasting time.",starts={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},ends={{npcID=224733,x=0.562,y=0.422,zoneID=14752}},coords={x=0.552,y=0.412,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Hand of the Vizier",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
