[81510] = {id=81510,name="Ship It!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="What a haul! I was able tae give a bit of what we found tae Dagran so he could finish off one of his projects. He should be here any minute. Ah, I can't hold back. Surprise! It's a gift tae help you get around.",objectivesText="Speak with Brann Bronzebeard Progress: Wait 'till ye see what Dagran has cooked up.",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Ship It!"},
