[81556] = {id=81556,name="Foreign Fog",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Pleasure to meet you, adventurer. I wonder if you might be willing to help me with some research? I'm sure you've noticed the fog beasts that have recently started encroaching upon this area. People see them as a bad omen, they always seem to show up during periods of ecological imbalance. I disagree with this assertion. Still as an expert in all vapor-based magics, I've been hired to find out where they're coming from so they can be cut off at the source.",objectivesText="Place the fog collector and collect fog samples from different areas occupied by fog beasts. Progress: Have you collected the fog samples?",starts={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},ends={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},coords={x=0.584,y=0.624,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="Foreign Fog"},
[81557] = {id=81557,name="Fog Tags",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2214,description="While I analyze these fog samples, I have another task for you. My employers have asked me to figure out where these fog beasts are coming from. I've developed these trackers. If you could, please attach them to an assortment of fog beasts. You'll have to get close, so... be careful. Hopefully they don't mind it too much!",objectivesText="Attach trackers to fog beasts in and around Taelloch. Progress: Have you attached all the trackers?",starts={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},ends={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},coords={x=0.584,y=0.624,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="Fog Tags"},
[81558] = {id=81558,name="Unnatural Predators",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2214,description="It would be no use tagging fog beasts to study if they all were to die, would it? Could you clear out some of the aggressive deepflayers that have flocked to feast on the fog beasts? They'll ruin my data if left unchecked, I'm sure of it.",objectivesText="Kill Deepflayer Hunters . Progress: Have you taken out the deepflayers?",starts={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},ends={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},coords={x=0.584,y=0.624,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="Unnatural Predators"},
[81559] = {id=81559,name="Fog Follower",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2214,description="With the trackers attached, we should be able to find out where the fog beasts are coming from. The trackers leave a residue in the air. It's invisible to the naked eye, but I can use the mists to reveal it in places where there's a high enough concentration. Theoretically, this should lead us to the places they most frequent. Maybe a nest! That I'll then have to report to my employer... hm. Anyway. Let's see what we can find.",objectivesText="Help Noli find the source of the fog beasts with her mist tracking ability. Progress: I know we'll be able to find them. Let's keep looking!",starts={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},ends={{npcID=221043,x=0.584,y=0.624,zoneID=14795}},coords={x=0.584,y=0.624,source="quest_giver",zoneID=14795},questType="world",worldTaskTitle="Fog Follower"},
