[81595] = {id=81595,name="Seasonal Start",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="We've uncovered loads of new treasures tae find in delves! There's no time tae wait. Let's get ye set up with the basics so you can get out there!",objectivesText="Review rewards offered by Reno Jackson , Sir Finley Mrrgglton , and the Delver's Guide .",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Seasonal Start"},
