[81692] = {id=81692,name="The Flame Within",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="When sparked, a tinderbox creates a flame that embodies the essence of its bearer's life journey. It is a reflection of your strength and inner spirit. In your travels, you have met many who could help us fashion a tinderbox capable of igniting a flame befitting your formidable spirit. Seek the assistance of Speaker Kuldas in Gundargaz. The earthen's knowledge will help create a more powerful tinderbox.",objectivesText="Seek out and gain the aid of Speaker Kuldas in Gundargaz.",starts={{npcID=214380,x=0.432,y=0.564,zoneID=14838}},ends={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},coords={x=0.432,y=0.564,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="The Flame Within"},
