[81906] = {id=81906,name="Whispers from the Web",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2216,description="Hey! Hey! You won't believe me, but I found the cutest, fuzziest puppy! With a bell! Around its neck! It gave me this to give to you. Take it, I gotta go catch that puppy!",objectivesText="Meet with Ct'nak in the Burrows of Azj-Kahet.",starts={{x=0.413,y=0.531,mapID=2215,npcID=221867}},ends={{x=0.413,y=0.531,mapID=2215,npcID=221867}},coords={mapID=2215,x=0.413,y=0.531},questType="world",worldTaskTitle="Whispers from the Web"},
