[81990] = {id=81990,name="The Light's Call",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Attention, residents of Hallowfall ! Urgent assistance is needed to reclaim the shadowed outskirts. As darkness grips countless family farms, your aid is needed to ignite the sacred flame and restore safety to our lands.",objectivesText="Report to Keyrra Flamestonge for further service.",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},ends={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="The Light's Call"},
