[82153] = {id=82153,name="Embassies and Envoys",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=14771,mapID=2248,description="We sailed for what seemed like an eternity. I must admit there were times when I worried we would arrive too late. But seeing all of you, united and strong, has rekindled my hope. Before we begin planning, we must set up a base of operations here in Dornogal.",objectivesText="Set up your faction's embassy in Dornogal.",starts={{npcID=216168,x=0.358,y=0.812,zoneID=14771}},ends={{npcID=214917,x=0.316,y=0.594,zoneID=14771}},coords={x=0.358,y=0.812,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Embassies and Envoys"},
