[82213] = {id=82213,name="A Batty Request",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I'll gather a selection of our major trade goods before we head out for the meet up, but I could use some help in gathering some additional items. Lately we've been struggling with collecting the best bat meat in Hallowfall . Could you gather some before you come to Dunelle's Kindness?",objectivesText="Collect 8 Shacklefang Leafnose Meat . Progress: Did you get the meat?",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},ends={{npcID=213145,x=0.412,y=0.53,zoneID=14838},{npcID=223267,x=0.684,y=0.446,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="A Batty Request"},
[82214] = {id=82214,name="Does Anyone Like Wasps?",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We haven't been able to gather resources from this area due to hornets moving in. We just haven't been able to spare the resources from the wall to deal with them. If you can, we'd all appreciate it.",objectivesText="Kill 10 Shacklefang Hornets . Progress: Damn those hornets. Wasps were bad enough when they were the size of my finger.",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},ends={{npcID=213145,x=0.412,y=0.53,zoneID=14838},{npcID=223267,x=0.684,y=0.446,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Does Anyone Like Wasps?"},
[82215] = {id=82215,name="Regular Fiber",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="There is a plant fiber that grows in Rumshackle and The Fangs that makes for an excellent rope. Because of the hornets, we haven't been able to collect it in a long time and are running very low in our supplies. While you are in the area, could you collect some?",objectivesText="Collect 5 Tough Ivy Fibers . Progress: The fibers are like magic. The ropes they make are strong, and supple.",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838},{npcID=223267,x=0.684,y=0.446,zoneID=14838}},ends={{npcID=213145,x=0.412,y=0.53,zoneID=14838},{npcID=223267,x=0.684,y=0.446,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Regular Fiber"},
[82216] = {id=82216,name="Economical Request",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I hear you've come from the surface? Did you meet the earthen? We used to trade with them, but after the Day of Darkness we struggled to send envoys. Those we sent never made it back. Honestly, we thought that they had perished. I'm going to try reaching out again. I'd like for you to write a letter of recommendation , in case we did something to offend them.",objectivesText="Write a letter of recommendation in Mereldar in Hallowfall . Progress: I hope this goes well. We really need additional resources.",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},ends={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Economical Request"},
[82217] = {id=82217,name="Underground Economics",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="After the Day of Darkness, we haven't seen or heard from the earthen. I don't know why. We used to be on good terms. I'd even have considered Merrix a friend, albeit an odd one. We need this to go well.",objectivesText="Assist the Arathi with trade negotiations in Dunelle's Kindness. Progress: We need this trade deal to go through.",starts={{npcID=225711,x=0.684,y=0.446,zoneID=14838}},ends={{npcID=225711,x=0.684,y=0.446,zoneID=14838}},coords={x=0.684,y=0.446,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Underground Economics"},
[82219] = {id=82219,name="Spice Up Your Life",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Flames blessing to you, . Trade has been going well now the Ringing Deeps are safe once again and things have, relatively, calmed down. Despite that, our General still won't breathe easily. She's wound tight and it's not healthy. An unhealthy general leads to an unhealthy army. So a day with the family. Can you pick some herbs for the meal? You'll want the big ones, don't bother with the small ones.",objectivesText="Gather 7 Light-Bathed Lotus in Hallowfall . Progress: Herbs bathed in the light of Beledar have a fantastic taste.",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},ends={{npcID=223267,x=0.684,y=0.446,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Spice Up Your Life"},
[82220] = {id=82220,name="Eagle Eye, Eagle Die",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The eagles out by the undersea have bathed in the light of Beledar, and it makes them particularly tasty. Could you get a few eagle fillets ? Take this harpoon with you, they can be feisty.",objectivesText="Collect 5 Eagle Fillets . Progress: Watch yourself. The eagles can easily injure you.",starts={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},ends={{npcID=223267,x=0.684,y=0.446,zoneID=14838}},coords={x=0.412,y=0.53,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Eagle Eye, Eagle Die"},
[82221] = {id=82221,name="Full Dress",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="A traditional Arathi family meal involves displaying the various medals, awards, and mementos of the family. Given my mother's illustrious career, it's taking quite a while. Would you mind helping with some of the decorations?",objectivesText="Help the Steelstrikes decorate their house in Mereldar in preparation for the upcoming meal. Progress: We have to get this meal right, my mother needs to unwind.",starts={{npcID=223267,x=0.684,y=0.446,zoneID=14838}},ends={{npcID=223267,x=0.684,y=0.446,zoneID=14838}},coords={x=0.684,y=0.446,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Full Dress"},
[82222] = {id=82222,name="Cooking With Style",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Sorry my daughter roped you into this. I'm sure you had better things to be doing. She has terrible manners. I'll have to have words with whoever raised her. Still, you are here. Would you like to join us for the more enjoyable activity? We're about to start cooking.",objectivesText="Help the Steelstrikes cook a meal in Mereldar. Progress: Why do they say a pinch of salt? Why not a handful? More ingredients has to be better.",starts={{npcID=223268,x=0.446,y=0.506,zoneID=14838}},ends={{npcID=224154,x=0.438,y=0.496,zoneID=14838}},coords={x=0.446,y=0.506,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Cooking With Style"},
[82223] = {id=82223,name="A Home Cooked Meal",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Home-cooked stew. There is nothing like it in the world. I grant you, it might not be as tasty as the stew from the Empires Edge Inn. But it was cooked by family. That's what makes it great. Join us. You have more than earned the right.",objectivesText="Have a meal at the Steelstrike House in Mereldar in Hallowfall . Progress: It's been such a long time since I had a meal with the entire family.",starts={{npcID=224154,x=0.438,y=0.496,zoneID=14838}},ends={{npcID=225745,x=0.446,y=0.506,zoneID=14838}},coords={x=0.438,y=0.496,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="A Home Cooked Meal"},
[82225] = {id=82225,name="Excavation Extravaganza",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,objectivesText="Excavation Efforts Supported",starts={{x=0.619,y=0.712,mapID=2248}},ends={{x=0.619,y=0.712,mapID=2248}},coords={mapID=2248,x=0.619,y=0.712},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Excavation Efforts Supported"}},worldTaskTitle="Excavation Extravaganza",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
