[82747] = {id=82747,name="Crossroads Plaza",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2339,description="Hello, outlander. Do you want to know about news from outside the city? The Crossroads is a key place for earthen to exchange information and goods, no matter their allegiances or edicts. My friend Bondaz unofficially maintains the square. He would be delighted to see you in person. I'm sure he has already heard a hundred different stories of how you and the outlanders made it to our isle.",objectivesText="Meet Bondaz in Crossroads Plaza.",starts={{npcID=224544,x=0.466,y=0.33,zoneID=14771}},ends={{npcID=224566,x=0.552,y=0.558,zoneID=14717}},coords={x=0.466,y=0.33,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Crossroads Plaza"},
[82778] = {id=82778,name="Hallowfall Fishing Derby",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Life is always on the edge here, $p. Nerubians, kobyss, hunger--there's always something ready to kill you. So we need to find times to relax, and challenge ourselves at something other than survival. Like fishing. My dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" So every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!",objectivesText="Catch these Trophy Fish before the Derby Dasher buff expires: Nibbling Minnow, Arathor Hammerfish, Queen's Lureback.",starts={{npcID=226846,x=0.442,y=0.616,zoneID=14838}},ends={{npcID=226846,x=0.442,y=0.616,zoneID=14838}},coords={x=0.442,y=0.616,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Hallowfall Fishing Derby"},
[82787] = {id=82787,name="Special Assignment: Rise of the Colossals",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,description="WQ",objectivesText="Kill Colossal beasts",questType="world",db2Objectives={{orderIndex=1,type=0,amount=3,objectID=224621,text="Colossals Slain"},{orderIndex=0,type=1,amount=3,objectID=224183,text="Gather Bleak Chum to bait Frothing Waters"}},worldTaskTitle="Special Assignment: Rise of the Colossals",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[82852] = {id=82852,name="Special Assignment: Lynx Rescue",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,description="WQ",objectivesText="Find and befriend a lost lynx Hunt Vanishing Nightmares Find and befriend a lost lynx",questType="world",db2Objectives={{orderIndex=1,type=0,amount=4,objectID=224922,text="Hunt Vanishing Nightmares"},{orderIndex=0,type=0,amount=1,objectID=225416,text="Find and befriend a lost lynx"},{orderIndex=2,type=0,amount=1,objectID=225022,text="Find and befriend a lost lynx"}},worldTaskTitle="Special Assignment: Lynx Rescue",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[83024] = {id=83024,name="The Stormrider's Bond",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="So, you think yourself worthy of a Stormrider's armor? We Stormriders were titan-made to fight and to ride stormrooks. Even so, we must prove our competence in battle before we gain clearance to wear Stormrider armor. I see no reason why you should not undergo the same challenges. Go. Show me you have the power of the storm within you.",objectivesText="Collect 50 Storm Spirits by slaying powerful creatures of Khaz Algar. Progress: Come back only when you've proven yourself worthy.",starts={{npcID=225347,x=0.352,y=0.382,zoneID=14771}},ends={{npcID=225347,x=0.352,y=0.382,zoneID=14771}},coords={x=0.352,y=0.382,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="The Stormrider's Bond"},
[83025] = {id=83025,name="A Sacred Connection",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="I may have granted you clearance to wear our armor, but to focus the storm's power through it as the greatest Stormriders do... The greatest Stormriders in our order do not merely possess the power of the storm. They have mastered it. And this mastery is forged over many battles. It is time to prove yourself as one of our best.",objectivesText="Collect 500 Storm Spirits by slaying powerful creatures of Khaz Algar. Progress: Your reward shall be properly equal to your efforts.",starts={{npcID=225347,x=0.352,y=0.382,zoneID=14771}},ends={{npcID=225347,x=0.352,y=0.382,zoneID=14771}},coords={x=0.352,y=0.382,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="A Sacred Connection"},
[83028] = {id=83028,name="Thieving Snufflers",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,objectivesText="Pilfered Cinderbrew recovered",starts={{x=0.495,y=0.349,mapID=2214}},ends={{x=0.495,y=0.349,mapID=2214}},coords={mapID=2214,x=0.495,y=0.349},questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=225339,text="Pilfered Cinderbrew recovered"}},worldTaskTitle="Thieving Snufflers",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
