[83182] = {id=83182,name="A Bloody Inheritance",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="When the kobyss killed my parents, they stole some of their most cherished things. Not me, obviously. Cherished items. While we are murdering kobyss, let's find them.",objectivesText="Retrieve Alyza's parents' items in the Hungering Pool in Hallowfall . Progress: Stupid kobyss. I hate them.",starts={{npcID=218062,x=0.524,y=0.502,zoneID=14838}},ends={{npcID=215254,x=0.496,y=0.506,zoneID=14838}},coords={x=0.524,y=0.502,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="A Bloody Inheritance"},
[83229] = {id=83229,name="Special Assignment: When the Deeps Stir",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,objectivesText="Awakened Elementals defeated",starts={{x=0.487,y=0.147,mapID=2214}},ends={{x=0.487,y=0.147,mapID=2214}},coords={mapID=2214,x=0.487,y=0.147},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=225898,text="Awakened Elementals defeated"}},worldTaskTitle="Special Assignment: When the Deeps Stir",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[83271] = {id=83271,name="There's Always Another Secret",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13390,mapID=2367,description="After me da' did whatever he did, the titans' machines are back online--even the ones here in Dornogal. Dagran was havin' enough fun with Brinthe askin' her a thousand questions, but now he's helpin' her sort through the Archive. An' now he wants your help. He was too excited to tell me why, but he wanted ye to meet him in the Archive.",objectivesText="Check in on Dagran Thaurissan II and Brinthe in the Archive in Dornogal.",starts={{npcID=214917,x=0.316,y=0.594,zoneID=14771}},ends={{npcID=226040,x=0.5,y=0.598,zoneID=13390}},coords={x=0.316,y=0.594,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="There's Always Another Secret"},
[83286] = {id=83286,name="What's Hidden Beneath Dornogal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13390,mapID=2367,description="Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence. Dagran's query may have to wait. I have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal. Perhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.",objectivesText="Restart the central mainframe in the Vault of Memory in Dornogal. Progress: Take your time. It has been here for millennia. I am sure it is not going anywhere.",starts={{npcID=226040,x=0.5,y=0.598,zoneID=13390}},ends={{npcID=226040,x=0.5,y=0.598,zoneID=13390}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=13390},questType="world",worldTaskTitle="What's Hidden Beneath Dornogal"},
[83315] = {id=83315,name="Preparing for the Unknown",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="This will be a long process. Longer, I fear, than Dagran can stay here in the Isles. But perhaps... There are many titan relics I can use as \"keys\" to unlocking information in the mainframe or to repair it. That may make the process go more quickly. Only time will tell. You have helped us enough, . Go back to Moira and tell her what we have discovered.",objectivesText="Return to Moira Thaurissan in Dornogal.",starts={{npcID=226040,x=0.5,y=0.598,zoneID=13390}},ends={{npcID=214917,x=0.316,y=0.594,zoneID=14771}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=13390},questType="world",worldTaskTitle="Preparing for the Unknown"},
[83328] = {id=83328,name="The Analysis Interface",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2322,description="This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.",objectivesText="Complete the Analyzing Sequence in the Analysis Interface.",starts={{x=0.626,y=0.492,mapID=2322,npcID=221891}},ends={{x=0.626,y=0.492,mapID=2322,npcID=221891}},coords={mapID=2322,x=0.626,y=0.492},questType="world",worldTaskTitle="The Analysis Interface"},
[83503] = {id=83503,name="Return to Dornogal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="The battle is finally over and I suppose it's time we lick our wounds. Head back to Dornogal, Champion. I'll be right there as soon as Khadgar is healthy enough to withstand travel.",objectivesText="Return to Dornogal in the Isle of Dorn and report what happened.",starts={{npcID=220688,x=0.36,y=0.354,zoneID=14838}},ends={{npcID=217864,x=0.404,y=0.258,zoneID=14771},{npcID=225897,x=0.252,y=0.66,zoneID=14771}},coords={x=0.36,y=0.354,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Return to Dornogal"},
[83529] = {id=83529,name="Hallowfall Fishing Derby",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Life is always on the edge here, $p. Nerubians, kobyss, hunger--there's always something ready to kill you. So we need to find times to relax, and challenge ourselves at something other than survival. Like fishing. My dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" So every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!",objectivesText="Catch these Trophy Fish before the Derby Dasher buff expires: Bismuth Butterling, Whispering Stargazer, Regal Dottyback. Progress: Any bites, <name>?",starts={{npcID=226846,x=0.442,y=0.616,zoneID=14838}},ends={{npcID=226846,x=0.442,y=0.616,zoneID=14838}},coords={x=0.442,y=0.616,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Hallowfall Fishing Derby"},
