[83555] = {id=83555,name="Mysterious Necklace",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="<The gem pulses with arcane energy, hinting at ancient magic woven into its very core.>",objectivesText="Return the necklace to Kalecgos at Mourning Rise in the Isle of Dorn .",starts={{npcID=228520,x=0.62,y=0.416,zoneID=14717}},ends={{npcID=227375,x=0.614,y=0.428,zoneID=14717}},coords={x=0.62,y=0.416,source="quest_giver",zoneID=14717},questType="world",worldTaskTitle="Mysterious Necklace"},
[83556] = {id=83556,name="Maybe You Shouldn't Touch That",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15000,mapID=2248,description="This necklace... It is clearly full of powerful magic, but... it is elusive--as if it is hiding its origin from me. You take another look. Maybe there's something obvious I'm missing.",objectivesText="Investigate the Emerald Necklace in Mourning Rise.",starts={{npcID=227375,x=0.614,y=0.428,zoneID=14717}},ends={{npcID=227208,zoneID=5031},{npcID=227208,zoneID=14882},{npcID=227208,zoneID=14990},{npcID=227208,zoneID=15000}},coords={x=0.614,y=0.428,source="quest_giver",zoneID=14717},questType="world",worldTaskTitle="Maybe You Shouldn't Touch That"},
[83643] = {id=83643,name="Somehow We Survived",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="What we experienced in Kel'Thuzad's pocket dimension is a timely reminder of what can happen when magic is used without regard to ethics or regulation. To me, this underlines the importance of the Kirin Tor. But, on the other hand, Kel'Thuzad was Kirin Tor. It is also a reminder of how power corrupts. Now that we have made sure these artifacts will not cause anyone else to go on an unexpected trip... Let's return to Aethas. Perhaps now more have responded to his letter.",objectivesText="Regroup with Kalecgos at the Tranquil Strand.",starts={{npcID=227392,x=0.616,y=0.428,zoneID=14717}},ends={{npcID=227407,x=0.31,y=0.578,zoneID=14717}},coords={x=0.616,y=0.428,source="quest_giver",zoneID=14717},questType="world",worldTaskTitle="Somehow We Survived"},
[83715] = {id=83715,name="Claimed Salvage",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,objectivesText="Goblins Slain Salvage Reclaimed",starts={{x=0.555,y=0.806,mapID=2214}},ends={{x=0.555,y=0.806,mapID=2214}},coords={mapID=2214,x=0.555,y=0.806},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=227374,text="Goblins Slain"},{orderIndex=1,type=1,amount=6,objectID=226020,text="Salvage Reclaimed"}},worldTaskTitle="Claimed Salvage",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[83718] = {id=83718,name="Eggstraction",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,objectivesText="Climbing Gear acquired Find a handhold on the cliff Collect Swarmite Egg",starts={{x=0.79,y=0.785,mapID=2255}},ends={{x=0.79,y=0.785,mapID=2255}},coords={mapID=2255,x=0.79,y=0.785},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=227401,text="Climbing Gear acquired"},{orderIndex=1,type=0,amount=1,objectID=227402,text="Find a handhold on the cliff"},{orderIndex=2,type=0,amount=7,objectID=227403,text="Collect Swarmite Egg"}},worldTaskTitle="Eggstraction",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[83723] = {id=83723,name="A Helping Hand",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Kalecgos's hypothesis that Dalaran's debris interferes with long-range teleportation seems correct. Mage portals have appeared along the shore, but no one has stepped through them. There are likely mages trapped within the portals. Or, something mana hungry--like felhunters--may be being lured here by the release of Dalaran's power. We must investigate. Mages of the Kirin Tor may be in danger. The felhunters are an acceptable risk. Let us not waste any more time.",starts={{npcID=212829,x=0.31,y=0.578,mapID=2248}},ends={{npcID=227409,x=0.298,y=0.578,mapID=2248}},coords={x=0.31,y=0.578,source="quest_giver",mapID=2248},questType="world",worldTaskTitle="A Helping Hand"},
[83762] = {id=83762,name="Critical Mass",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="This is exactly what I had feared. Thalen Songweaver's notes on the mana bomb he devised to devastate Theramore were under guard in Dalaran. Few knew of this. I argued they should be destroyed. But others argued if such a bomb was again created, we would need them to disarm it. And now those notes are both the problem and the solution. Thankfully, I have read these notes, . I will walk you through disarming the mana bomb.",objectivesText="Help Lady Jaina Proudmoore disarm the mana bomb in the Breathing Pit.",starts={{npcID=227529,x=0.352,y=0.53,zoneID=14752}},ends={{npcID=229763,x=0.354,y=0.524,zoneID=14752}},coords={x=0.352,y=0.53,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Critical Mass"},
[83764] = {id=83764,name="Too Powerful, Too Dangerous",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Some of the relics the nerubians now possess were housed in carefully-designed containment vaults on Dalaran. That is how dangerous and powerful they are. With those vaults gone, the only course of action we can take is to destroy them. In hindsight, it seems a grave mistake to have gathered so many powerful artifacts in one place--even if that place was Dalaran. I would trust no one else with this task, . Find and destroy those artifacts.",objectivesText="Find dangerous artifacts scattered around in the Breathing Pit and destroy them.",starts={{npcID=229763,x=0.354,y=0.524,zoneID=14752}},ends={{npcID=228963,x=0.314,y=0.51,zoneID=14717}},coords={x=0.354,y=0.524,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Too Powerful, Too Dangerous"},
[83827] = {id=83827,name="Silence the Song",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="The sirens... they're out there! And I wonder... was it the crystal or these creatures that the Kul Tirans named this isle after? Whichever it may be, these sirens' call has lured many of our forces to their doom. Our goblin allies have prepared a device to remove the control they have over our troops. Eliminate these \"sirens\" and dispel the charm that holds our troops captive.",objectivesText="Free 7 Charmed Troops and slay Macabea The Sea Banshee . Progress: Have you eliminated the siren threat?",starts={{npcID=232753,x=0.452,y=0.678,zoneID=10416}},ends={{npcID=232753,x=0.452,y=0.678,zoneID=10416}},coords={x=0.452,y=0.678,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="Silence the Song"},
[83930] = {id=83930,name="Deworming Solution",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,objectivesText="Worms Slain",starts={{x=0.532,y=0.395,mapID=2214}},ends={{x=0.532,y=0.395,mapID=2214}},coords={mapID=2214,x=0.532,y=0.395},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=227802,text="Worms Slain"}},worldTaskTitle="Deworming Solution",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[84001] = {id=84001,name="Cart Blanche",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="Our mining team is making great progress. All our carts have already been loaded with ore samples and sent back to camp. There's a problem though... None of the carts made it to camp due to trouble on the tracks! Please repair the tracks and collect any lost ore if you can so we can get those samples to camp.",objectivesText="Repair 2 Mine Tracks, clear 5 Crashed Mine Carts, and collect 12 Ore Samples . Progress: Are the mine carts getting through now?",starts={{npcID=232730,x=0.484,y=0.528,zoneID=10416}},ends={{npcID=232730,x=0.484,y=0.528,zoneID=10416}},coords={x=0.484,y=0.528,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="Cart Blanche"},
[84022] = {id=84022,name="Uniting Severed Threads",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="You have done well to ally Anub'azal and Nizrek to our cause. It is time that we solidify this triumverate relationship between us all. We will conference via shadecasters. Activate them when you're ready to begin.",objectivesText="Join forces with the Weaver, the General, and the Vizier to forge the Severed Threads. Progress: I wonder how our three potent personalities will work together. Only time will tell, I suppose.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Uniting Severed Threads"},
[84225] = {id=84225,name="Eggstinction",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="We should really get outta here, but... Do you see those eggs over there? If those monsters hatch them all, this place will be swarming with crabs when the storm clears. Ugh, there's just too many to destroy by hand. We're gonna need some help! Suzie's got a lot of helpful items back at the camp... or maybe my broiler will work? I dunno, champ. Grab somethin' to get rid of those eggs!",objectivesText="Eliminate 12 Egg Tenders and 12 Spawning Clutches. Progress: Did you get rid of the eggs?",starts={{npcID=231937,x=0.636,y=0.664,zoneID=10416}},ends={{npcID=227814,x=0.69,y=0.476,zoneID=10416},{npcID=231937,x=0.636,y=0.664,zoneID=10416}},coords={x=0.636,y=0.664,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="Eggstinction"},
[84241] = {id=84241,name="Shoreline Stand",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15827,mapID=2369,description="This storm will not drive me from my sacred duty. This cave must be defended at all costs! This new crystal may still be shrouded in mystery, but we will never understand its secrets or its relation to Beledar if we allow it to fall into the grasp of these wretches who crawl from the ocean's abyss. Stand with me, . Together, we shall defend this shoreline to our final breath.",objectivesText="Eliminate 15 Brinebound Wraith and Tide-Champion Korval . Progress: Is the crystal safe?",starts={{npcID=232297,x=0.438,y=0.236,zoneID=10416}},ends={{npcID=232297,x=0.438,y=0.236,zoneID=10416}},coords={x=0.438,y=0.236,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="Shoreline Stand"},
[84248] = {id=84248,name="A Ritual of Runes",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=10416,mapID=2369,description="I went to investigate a cave nearby, and I came across some Bloodwake vrykul that were conjuring something... something that activated my threat mitigation protocols. I calculate that if they complete their ritual, it would be disastrous for the island. , please assess the cave and stop their ritual before something terrible occurs!",objectivesText="Destroy 5 Summoning Runes and eliminate Inhyldir the Cursed . Progress: Did you disrupt the ritual?",starts={{npcID=233139,x=0.514,y=0.48,zoneID=10416}},ends={{npcID=233139,x=0.514,y=0.48,zoneID=10416}},coords={x=0.514,y=0.48,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="A Ritual of Runes"},
[84252] = {id=84252,name="Peak Precision",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="Flying? It ain't for me. Sally Boltwrench wanted me to activate a bunch of survey machines to monitor the wind currents, but it's too rough up there and the heights give me the heebie jeebies. An' I get sick every time I try. Use the Go-Pack to activate the machines for me. I'll owe ya one!",objectivesText="Activate 6 Survey Machines using the Experimental Go-Pack to help reach them. Progress: Did you switch those machines on?",starts={{npcID=232255,x=0.422,y=0.49,zoneID=10416}},ends={{npcID=227814,x=0.69,y=0.476,zoneID=10416}},coords={x=0.422,y=0.49,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="Peak Precision"},
