[84490] = {id=84490,name="The Great Vault",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Many of Dornogal's systems have been dormant for millennia and are now back online. One that you might find useful, , is the Great Vault. Once, this cache of armor and weapons would have supported the earthen in their Oathsworn duty to protect Dornogal. Now it is extended to you with the expectation that you use what you find there to aid others along your quest. The Vault is housed here in Dornogal within the Council's Treasury. The Councilward has granted you full access to its contents.",objectivesText="Obtain a piece of loot from the Great Vault. Progress: The vault is yours to peruse, <name>.",starts={{npcID=229336,x=0.518,y=0.456,zoneID=14771}},ends={{npcID=229336,x=0.518,y=0.456,zoneID=14771}},coords={x=0.518,y=0.456,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="The Great Vault"},
[84680] = {id=84680,name="Rock 'n Stone Revival",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="The attacking vrykul harness salt and brine elementals, turning them against their foes. To counter their assault, we can harness them as well. Use this Rock Reviver to unleash the elementals residing within nearby stones, transforming them into powerful allies. With their help, we can defeat this vrykul threat.",objectivesText="8 Restless Pebbles or Stones revived, 8 Bloodbrine horrors and the Bloodbrine Monstrosity defeated. Progress: Have you stopped the vrykul and their elemental thralls?",starts={{npcID=228096,x=0.692,y=0.428,zoneID=10416}},ends={{npcID=228096,x=0.692,y=0.428,zoneID=10416}},coords={x=0.692,y=0.428,source="quest_giver",zoneID=10416},questType="world",worldTaskTitle="Rock 'n Stone Revival"},
[84682] = {id=84682,name="Of Pacts and Patrons",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The Severed Threads is ready for you and your allies. You will be a lit torch to Ansurek's webs. The General, the Vizier, and, myself, the Weaver, each have differing methods of combating our foes... and different benefits of aiding our accomplices. You may prefer to prioritize one, or perhaps to dabble with all three instead. Meet with our representatives, and inform yourself on our varying practices. Then you may forge your first Pact. Don't worry, little morsel, no choice is ever permanent.",objectivesText="Speak with the representatives of the Severed Threads, then forge your first Pact. Progress: Have you considered your options?",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Of Pacts and Patrons"},
