[85913] = {id=85913,name="Side Gig: Cleanup Detail",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2346,description="We're looking for someone with a strong arm and stronger stomach to help deal with all the blood monsters popping up in the Ringing Deeps. The cleanup crews keep getting eaten and it's murder on our schedule. You up for it?",objectivesText="Kill blood monstrosities in the Writhing Fields.",starts={{npcID=231063,x=0.168,y=0.522,zoneID=15347}},ends={{npcID=231063,x=0.168,y=0.522,zoneID=15347}},coords={x=0.168,y=0.522,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Cleanup Detail"},
[85914] = {id=85914,name="Side Gig: Coolant Matters",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Sounds like the old Black Blood pipes in the Ringing Deeps are thawing out, but we haven't figured out a solution for all the goo they're packed with just yet. A few more budgetary meetings, though, and we're on it. In the meantime, we earmarked a little cash for some temp help. That's you. Get out there and refreeze those pipes.",objectivesText="Ride Pamsy's Rocketboard in the Writhing Fields and freeze the pipeline. Progress: Try not to freeze any important bits off. We're not offering medical.",starts={{npcID=231063,x=0.168,y=0.522,zoneID=15347}},ends={{npcID=231063,x=0.168,y=0.522,zoneID=15347}},coords={x=0.168,y=0.522,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Coolant Matters"},
