[85944] = {id=85944,name="Side Gig: Blood Type",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2346,description="Darkfuse was up to all sorts of questionable research out in the Ringing Deeps and, well, everywhere, really. Anyway, they had to write some of it down. Nab whatever notes you can find and bring them back to me. Don't look at me like that. It's not intellectual dishonesty, it's industrial espionage!",objectivesText="Collect 8 Darkfuse Research Notes in the Writhing Fields. Progress: Got the goods?",starts={{npcID=231062,x=0.168,y=0.522,zoneID=15347}},ends={{npcID=231062,x=0.168,y=0.522,zoneID=15347}},coords={x=0.168,y=0.522,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Blood Type"},
[85945] = {id=85945,name="Side Gig: Blood-B-Gone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Do you have any idea how hard it is to get dried blood stains out of your laundry? Well, you might, I guess. Steamwheedle's finest are working on a new detergent specifically formulated to deal with this pressing issue! And while the blood fields in the Ringing Deeps might be bad for the environment, and you, they're the perfect place to field test our latest formulations. Just give the blood slimes out there a quick hose down and let us know what happens.",objectivesText="Test Blood-B-Gone on 8 blood slimes in the Writhing Fields. Progress: We've got a market to corner here.",starts={{npcID=231062,x=0.168,y=0.522,zoneID=15347}},ends={{npcID=231062,x=0.168,y=0.522,zoneID=15347}},coords={x=0.168,y=0.522,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Blood-B-Gone"},
[85946] = {id=85946,name="The Great Crab Breakout",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Arrived at Pleasant Heights Supermarket Crabs covered for Talk to Worker 1 Talk to Worker 2 Talk to Manager",questType="world",db2Objectives={{orderIndex=0,type=19,amount=0,objectID=35570,text="Arrived at Pleasant Heights"},{orderIndex=1,type=0,amount=3,objectID=234030,text="Supermarket Crabs covered for"},{orderIndex=2,type=0,amount=1,objectID=238151,text="Talk to Worker 1"},{orderIndex=3,type=0,amount=1,objectID=238152,text="Talk to Worker 2"},{orderIndex=4,type=0,amount=1,objectID=238153,text="Talk to Manager"}},worldTaskTitle="The Great Crab Breakout"},
[85960] = {id=85960,name="Side Gig: Lost in the Sauce",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2346,description="Some of the workers forced by the Darkfuse to work the blood fields never made it home. We've got reports that they might be lost in whatever the \"Unseeming\" is. Apparently it's got something to do with the big blood puddles? Sounds like a job for someone more expendable--I mean experienced, than me.",objectivesText="Rescue 8 Lost Goblins from the Unseeming in the Writhing Fields.",starts={{npcID=231063,x=0.168,y=0.522,zoneID=15347}},ends={{npcID=231063,x=0.168,y=0.522,zoneID=15347}},coords={x=0.168,y=0.522,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Lost in the Sauce"},
[85962] = {id=85962,name="Side Gig: Unseemly Reagents",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2346,description="There's all sorts of weirdness going on in the Ringing Deeps thanks to all that Black Blood still lying around. And where there's madness and mutation, there's opportunity! Get out there and see what sort of horrific but potentially lucrative reagents you can scrape up.",objectivesText="Collect 10 Unseemly Growths in the Writhing Fields. Progress: Try not to go crazy until after delivery, ok?",starts={{npcID=231062,x=0.168,y=0.522,zoneID=15347}},ends={{npcID=231062,x=0.168,y=0.522,zoneID=15347}},coords={x=0.168,y=0.522,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Unseemly Reagents"},
[86177] = {id=86177,name="Side Gig: The Tides Provide",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="You look like the type who ain't shy to get your hands dirty. Up for a little treasure hunting? Word has it that a ship exploded not far off the Kaja'Coast. Go to shore and see what the tide's brought in. \"Finders keepers\" is one of the foundational tenets of goblin society, after all.",objectivesText="Collect 5 Shiny Treasures along the Kaja'Coast. Progress: Gotta bring your own shovel. I never supply nothin', that's a liability waitin' to happen.",starts={{npcID=231064,x=0.198,y=0.528,zoneID=15347}},ends={{npcID=231064,x=0.198,y=0.528,zoneID=15347}},coords={x=0.198,y=0.528,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: The Tides Provide"},
[86178] = {id=86178,name="Side Gig: Cleanin' the Coast",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,mapID=2346,description="It's time for the Venture Company to earn a lil' good faith. We're lookin' to hire some efficient workers like yourself to clean up the Kaja'Coast. Could you help us kill some of the kaja'mentals that have gone... well, mental out there? We'll toss some competitive compensation your way.",objectivesText="Kill 10 Agitated Kaja'mentals on the Kaja'Coast.",starts={{npcID=231065,x=0.196,y=0.528,zoneID=15347}},ends={{npcID=231065,x=0.196,y=0.528,zoneID=15347}},coords={x=0.196,y=0.528,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Cleanin' the Coast"},
[86179] = {id=86179,name="Side Gig: Lucky Break's Big Break",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,mapID=2346,description="You know the Lucky Break Mines over on the Kaja'Coast? Settin' those up was kind of a rush job. Darkfuse didn't exactly give Venture a whole lotta time to reinforce the place. Long story short, there's a good chance the mines might collapse if we don't fix 'em up. That wouldn't be good news for anyone, especially not my wallet. Could you head over and rig up some support beams in the mines? That should do the trick for now.",objectivesText="Place 6 Support Beams in the Lucky Break Mines on the Kaja'Coast.",starts={{npcID=231065,x=0.196,y=0.528,zoneID=15347}},ends={{npcID=231065,x=0.196,y=0.528,zoneID=15347}},coords={x=0.196,y=0.528,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Lucky Break's Big Break"},
[86180] = {id=86180,name="Side Gig: Infested Waters",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,mapID=2346,description="So, my workers were supposed to be loadin' up some kaja'mite over in Zuldazar, but apparently the transport got upended and a shark swallowed the whole crate. I tried submittin' an insurance claim, but they ain't buyin' it. So we got no choice but to get that kaja'mite back ourselves. Down for a little shark huntin'?",objectivesText="Retrieve the Swallowed Kaja'mite from the Kaja' Carrying Razormaw on the Kaja'Coast. Progress: You think the shark might end up bein' able to talk? I kinda want a talkin' shark.",starts={{npcID=231065,x=0.196,y=0.528,zoneID=15347}},ends={{npcID=231065,x=0.196,y=0.528,zoneID=15347}},coords={x=0.196,y=0.528,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Side Gig: Infested Waters"},
