[86363] = {id=86363,name="The Better Part of Valorstones",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="It's been many months since we arrived in Dornogal and there's still more to learn of Valorstones . It turns out they can be found beyond Azeroth! This discovery opens up entirely new avenues of research. With new research comes a need for new supplies. Bring me some, and we'll help upgrade your gear to new heights.",objectivesText="Collect 50 Valorstones while adventuring in Khaz Algar, Undermine, and K'aresh, then return to Cuzolth and upgrade a piece of Season 3 equipment. Progress: There's no need to hurry. But if you wouldn't mind hurrying anyway...",starts={{npcID=219226,x=0.518,y=0.42,zoneID=14771}},ends={{npcID=219226,x=0.518,y=0.42,zoneID=14771}},coords={x=0.518,y=0.42,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="The Better Part of Valorstones"},
[86364] = {id=86364,name="Crests from the Ether",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Wonderful. Valorstones are capable of upgrading lower-level equipment on their own. That being said, Valorstones can only do so much. More powerful equipment will also require Ethereal Crests to upgrade to their full potential. These crests are rewarded through many different activities. Ethereal Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Bring me fifteen Weathered Ethereal Crests, and we can help you upgrade some gear further.",objectivesText="Acquire 15 Weathered Ethereal Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal. Progress: If you're having a hard time finding Weathered Ethereal Crests, you can search for hidden treasures around Khaz Algar, Undermine, or K'aresh. There's no shortage of those treasures!",starts={{npcID=219226,x=0.518,y=0.42,zoneID=14771}},ends={{npcID=219226,x=0.518,y=0.42,zoneID=14771}},coords={x=0.518,y=0.42,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Crests from the Ether"},
[86365] = {id=86365,name="Crest Transmutation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="My friend, these Crests are magnificent. It looks like they can be transmuted into different tiers! If you find yourself no longer in need of a lower-tier Crest, then I can transmute them to be more powerful. I can also transmute Crests into a weaker tier. Let's practice the transmutation process. Here's a few Carved Ethereal Crests. Speak to me and I can transform them into Weathered Ethereal Crests for you.",objectivesText="Bring 15 Carved Ethereal Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Ethereal Crests. Progress: If you lose those Carved Ethereal Crests, you can find more from powerful creatures around K'aresh. I've heard there's quite a variety of them!",starts={{npcID=219226,x=0.518,y=0.42,zoneID=14771}},ends={{npcID=219226,x=0.518,y=0.42,zoneID=14771}},coords={x=0.518,y=0.42,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Crest Transmutation"},
