[86728] = {id=86728,name="Operation: Floodgate: Disposing of the Garbage",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Hey, pal. I've heard murmurs of a real piece of work trying to siphon off energy at the Waterworks in the Ringing Deeps. Stealing from our stone friends ain't good for business, and it certainly ain't something we're willing to let continue. I know you've made a name for yourself for disposing of the trash, and bad business folks are certainly as trashy as they come. Do me a favor, will ya? Weapons are optional, but attitude is required... if you catch my drift.",objectivesText="Defeat Geezle Gigazap in Operation: Floodgate. Progress: Yo, you take care of that \"thing\" for me?",starts={{npcID=231045,x=0.434,y=0.514,zoneID=15347}},ends={{npcID=231045,x=0.434,y=0.514,zoneID=15347}},coords={x=0.434,y=0.514,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Operation: Floodgate: Disposing of the Garbage",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
