[87001] = {id=87001,name="Warrant: Shatterpulse",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="The horrifying monstrosity known as Shatterpulse lies hidden in a stasis cell at Shadowpoint. It is not kept as a prisoner, but as a weapon to be unleashed upon us when we are least prepared. Create a key to open Shatterpulse's stasis cell revealing this threat to everyone.",objectivesText="Collect a Calculation Container , Marking Matrix and some Void Fused Resin to create a key. Progress: Combine the items to form the Stasis Cell Key.",starts={{x=0.485,y=0.586,mapID=2472,npcID=238265}},ends={{x=0.485,y=0.586,mapID=2472,npcID=238265}},coords={mapID=2472,x=0.485,y=0.586},questType="world",worldTaskTitle="Warrant: Shatterpulse"},
[87327] = {id=87327,name="A Challenger's Resilience",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16865,mapID=2339,description="Wow , you've taken on some unbelievably scary dungeons AND lived to tell me about it! Come speak with me and I'll see about making your most challenging Keystones more Resilient.",objectivesText="Meet with Lindormi to learn about Resilient Keystones . Progress: You have achieved much. Your deeds are Legendary.",starts={{npcID=197711,x=0.532,y=0.562,zoneID=13862},{npcID=197711,x=0.538,y=0.39,zoneID=14771},{npcID=197711,x=0.422,y=0.588,zoneID=15969},{npcID=197915,x=0.436,y=0.313,zoneID=4813},{npcID=197915,zoneID=7546},{npcID=197915,zoneID=7673},{npcID=197915,zoneID=8064},{npcID=197915,x=0.61,y=0.315,zoneID=8910},{npcID=197915,zoneID=9164},{npcID=197915,zoneID=9354},{npcID=197915,x=0.194,y=0.481,zoneID=9526},{npcID=197915,zoneID=12841},{npcID=197915,zoneID=13334},{npcID=197915,zoneID=13982},{npcID=197915,zoneID=14011},{npcID=197915,x=0.69,y=0.81,zoneID=14032},{npcID=197915,zoneID=14882},{npcID=197915,zoneID=14883},{npcID=197915,zoneID=14971},{npcID=197915,zoneID=15103},{npcID=197915,zoneID=16104},{npcID=197915,x=0.387,y=0.494,zoneID=16359},{npcID=197915,x=0.779,y=0.077,zoneID=16395}},ends={{npcID=197711,x=0.532,y=0.562,zoneID=13862},{npcID=197711,x=0.538,y=0.39,zoneID=14771},{npcID=197711,x=0.422,y=0.588,zoneID=15969}},coords={x=0.532,y=0.562,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="A Challenger's Resilience",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[87342] = {id=87342,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",objectivesText="Honor the Midsummer Bonfire in the Isle of Dorn.",starts={{npcID=238236,x=0.482,y=0.516,zoneID=14771}},ends={{npcID=516698,x=0.484,y=0.517,zoneID=14771}},coords={x=0.482,y=0.516,source="quest_giver",zoneID=14771},questType="world",worldTaskTitle="Honor the Flame"},
[87343] = {id=87343,name="Warrant: Hollowbane",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="Shadowguard forces in Shadow Point have rallied around an enigmatic champion know as Hollowbane. Though the Hollowbane's existence is unconfirmed, we have located a travel portal supposedly used by the champion. Unlock the portal and expose Hollowbane so they may be confronted and eliminated.",objectivesText="Combine an Umbral Facade , Energy Encapsulation and a Bag of Veilshards to create a portal key.",starts={{x=0.485,y=0.581,mapID=2472,npcID=238269}},ends={{x=0.485,y=0.581,mapID=2472,npcID=238269}},coords={mapID=2472,x=0.485,y=0.581},questType="world",worldTaskTitle="Warrant: Hollowbane"},
[87344] = {id=87344,name="A Key Threat",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="Tazavesh is a city rife with turmoil, beset by countless dangers. We could always use your help. Check our warrant board, and see if you have what it takes to eliminate our most wanted threats.",objectivesText="Complete a warrant and eliminate the threat to our city. Progress: Have you completed a warrant.",starts={{npcID=238255,x=0.486,y=0.578,zoneID=15781}},ends={{npcID=238255,x=0.486,y=0.578,zoneID=15781}},coords={x=0.486,y=0.578,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="A Key Threat"},
[87345] = {id=87345,name="Warrant: Xy'vox the Twisted",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Xy'vox the Twisted the former constable of Tazavesh, hailed from a powerful cartel family. Unknown to most, the family's power was obtained from illegal crimes, all conveniently overlooked by Xy'vox. When the truth came out, Xy'vox went into hiding. I believe the constable never left town, instead hides here in plain sight, continuing criminal activities. Create a Refuge Dampener to reveal Xy'vox to all of Tazavesh.",objectivesText="Collect a Tazavesh Facade , Ethereal Seal and a Zo'kita Fruit .",starts={{x=0.485,y=0.584,mapID=2472,npcID=238271}},ends={{x=0.485,y=0.584,mapID=2472,npcID=238271}},coords={mapID=2472,x=0.485,y=0.584},questType="world",worldTaskTitle="Warrant: Xy'vox the Twisted"},
