[87355] = {id=87355,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",objectivesText="Honor the Midsummer Bonfire in Hallowfall",starts={{npcID=238338,x=0.424,y=0.516,zoneID=14838}},ends={{npcID=516884,x=0.424,y=0.516,zoneID=14838}},coords={x=0.424,y=0.516,source="quest_giver",zoneID=14838},questType="world",worldTaskTitle="Honor the Flame"},
[87356] = {id=87356,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",objectivesText="Honor the Midsummer Bonfire in Azj-Kahet",starts={{npcID=238339,x=0.556,y=0.434,zoneID=14752}},ends={{npcID=516887,x=0.556,y=0.434,zoneID=14752}},coords={x=0.556,y=0.434,source="quest_giver",zoneID=14752},questType="world",worldTaskTitle="Honor the Flame"},
