[87546] = {id=87546,name="Warrant: Purple Peat",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="In restoring the eco domes, much of the contaminated plant life was removed, allowing the soil to heal. However, one corrupted lasher escaped our notice. Nicknamed \"Purple Peat\" by the dome technicians, it continues to spread its roots and seeds into Eco-Dome: Primus. The plant hides safely in an old stasis cell outside the dome. Construct a device to remove the protective cell and expose the plant so it can be eliminated.",objectivesText="Combine a Large Sticky Voidmass , Energy Encapsulation and a Untethered Battery create a create a key to unlock the stasis sphere.",starts={{x=0.485,y=0.583,mapID=2472,npcID=238919}},ends={{x=0.485,y=0.583,mapID=2472,npcID=238919}},coords={mapID=2472,x=0.485,y=0.583},questType="world",worldTaskTitle="Warrant: Purple Peat"},
[87569] = {id=87569,name="Legally Mandated Break",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Arrived at Shipping and Handling Garage Take your Legally Mandated Break",questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=239001,text="Take your Legally Mandated Break"},{orderIndex=0,type=19,amount=0,objectID=36572,text="Arrived at Shipping and Handling Garage"}},worldTaskTitle="Legally Mandated Break"},
[87582] = {id=87582,name="Delves: Site of Madness",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Hey, pal. Some real weird stuff has been happening south of Gutterville. Some of my friends have gone missing, and their family's worried about them. How about you take that can-do attitude of yours down there and see if you can figure out what happened? I'm sure there will be some compensation to make it up to you too. Trust me.",objectivesText="Complete the Excavation Site 9 delve on any difficulty. Progress: Yo, did you figure out what happened down there?",starts={{npcID=231045,x=0.434,y=0.514,zoneID=15347}},ends={{npcID=231045,x=0.434,y=0.514,zoneID=15347}},coords={x=0.434,y=0.514,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Delves: Site of Madness",db2QuestInfoID=288,db2QuestInfoName="Delve"},
[87583] = {id=87583,name="Delves: The Sluice Contains the Juice",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Buddy, pal, . Some Darkfuse have taken root down in the sewers here in Undermine. They're shaking down hard-working goblins for cash, stealing their lunches, and sometimes even destroying their flamingo lawn ornaments! Those Darkfuse suffer from a real lack of decorum, let me tell you. I know you'll do the right thing and help us out, especially after such a tearjerker of a story.",objectivesText="Complete the Sidestreet Sluice delve on any difficulty.",starts={{npcID=231045,x=0.434,y=0.514,zoneID=15347}},ends={{npcID=231045,x=0.434,y=0.514,zoneID=15347}},coords={x=0.434,y=0.514,source="quest_giver",zoneID=15347},questType="world",worldTaskTitle="Delves: The Sluice Contains the Juice",db2QuestInfoID=288,db2QuestInfoName="Delve"},
