[89490] = {id=89490,name="Warrant: Arcana-Monger So'zer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="Arcana-Monger So'zer is responsible for a spree of thefts throughout Tazavesh that have resulted in the loss of magic relics, wands, and several crates of highly toxic Zo'kita fruit. Informants suggest that So'zer may be compelled to reveal himself if presented with a highly prized arcane relic. Create an item tempting enough to trick this criminal into revealing themselves.",objectivesText="Combine an Arcane Runed Sigil with a Charged Crystal and a Smuggler's Mark to create an Arcane Lure to reveal So'zer.",starts={{x=0.484,y=0.59,mapID=2472,npcID=241951}},ends={{x=0.484,y=0.59,mapID=2472,npcID=241951}},coords={mapID=2472,x=0.484,y=0.59},questType="world",worldTaskTitle="Warrant: Arcana-Monger So'zer"},
[90663] = {id=90663,name="Stealing What is Ours",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Ve'nari has called in a lot of favors to get the Oasis reclamation effort off the ground. Plenty of Tazavesh merchants have donated to the cause, though some have seen fit to help themselves instead. A large shipment of stasis-sealed items was stolen from the docks by an untrustworthy importer. I could use someone of your skill to recover the shipment.",objectivesText="Speak with Xy'dax and recover the Missing Imports . Progress: Have you recovered my missing items?",starts={{npcID=238016,x=0.576,y=0.578,zoneID=15781}},ends={{npcID=238016,x=0.576,y=0.578,zoneID=15781}},coords={x=0.576,y=0.578,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="Stealing What is Ours"},
[90729] = {id=90729,name="Win-Win Situation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway! Xy'daz has been ripping people off for years. It's his turn to take a loss! Now, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!",objectivesText="Sell 6 Shadowtrade Overstock. Progress: Did you sell the items?",starts={{npcID=238016,x=0.576,y=0.578,zoneID=15781}},ends={{npcID=238016,x=0.576,y=0.578,zoneID=15781}},coords={x=0.576,y=0.578,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="Win-Win Situation"},
[90747] = {id=90747,name="The Wrong Bluecephalus",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2371,description="We may have gotten off on the wrong foot, but there's something you should know. That old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along. A rare bluecephalus, worth a fortune! You might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!",objectivesText="Speak with Ba'eth and others. Progress: Are you ready to help?",starts={{npcID=243291,x=0.468,y=0.366,zoneID=15781}},ends={{npcID=243926,x=0.484,y=0.416,zoneID=15781}},coords={x=0.468,y=0.366,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="The Wrong Bluecephalus"},
[90769] = {id=90769,name="A Blue for You",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Why you want such a strange beast? I save many better items just for you. What about some soap? But, I not deny $p heart's desire.",starts={{npcID=243915,x=0.488,y=0.412,zoneID=15781}},ends={{npcID=243915,x=0.488,y=0.412,zoneID=15781}},coords={x=0.488,y=0.412,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="A Blue for You"},
[90770] = {id=90770,name="The Grift",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16182,mapID=2371,description="Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. Many more bargains to find in spots where treasures lie waiting. You know where to look? Go to dis special place and find treasures, I give the blue beast to you.",objectivesText="Enter Untethered Space and recover the items Griftah requires. Progress: Did you find da treasures?",starts={{npcID=243915,x=0.488,y=0.412,zoneID=15781}},ends={{npcID=243915,x=0.488,y=0.412,zoneID=15781}},coords={x=0.488,y=0.412,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="The Grift"},
[90773] = {id=90773,name="Meat My Business",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Since I am helping you, I'm sure you won't mind returning the favor. I have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands? I've got a list of what I need. Bring me those items, and I'll tell you what you need to know.",objectivesText="Collect 12 Dustback Flank , 5 Siltwing Tail , and 5 Swoopwing Eggs . Progress: You've collect all the meat?",starts={{npcID=243926,x=0.484,y=0.416,zoneID=15781}},ends={{npcID=243926,x=0.484,y=0.416,zoneID=15781}},coords={x=0.484,y=0.416,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="Meat My Business"},
[91093] = {id=91093,name="More Than Just a Phase",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds. Aid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.",objectivesText="Complete activities while phase diving in Untethered Space on K'aresh. Progress: I dream of a day when we K'areshi can roam these lands freely and without fear.",starts={{npcID=238255,x=0.486,y=0.578,zoneID=15781},{npcID=241624,x=0.504,y=0.362,zoneID=15336}},ends={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},coords={x=0.486,y=0.578,source="quest_giver",zoneID=15781},questType="world",worldTaskTitle="More Than Just a Phase"},
[91476] = {id=91476,name="Behind Enemy Lines",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="My friend, we've finished working on some new tools to ensure you'll do some real damage to the Shadowguard. Come by and let's sort it out together.",objectivesText="Report to Zo'turu at Shadow Point.",starts={{x=0.42,y=0.221,mapID=2371,npcID=245344}},ends={{npcID=245344,x=0.42,y=0.222,zoneID=15336}},coords={mapID=2371,source="quest_giver",x=0.42,y=0.222},questType="world",worldTaskTitle="Behind Enemy Lines",db2QuestInfoID=62,db2QuestInfoName="Raid"},
[91477] = {id=91477,name="Behind Enemy Lines II",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.",objectivesText="Report to Zo'turu at Shadow Point.",starts={{x=0.42,y=0.221,mapID=2371,npcID=245344}},ends={{npcID=245344,x=0.42,y=0.222,zoneID=15336}},coords={mapID=2371,source="quest_giver",x=0.42,y=0.222},questType="world",worldTaskTitle="Behind Enemy Lines II",db2QuestInfoID=62,db2QuestInfoName="Raid"},
